        id: context.occurrenceId,
        scheduleId: context.scheduleId,
        definitionHash,
        status: 'running',
        reason: null,
        targetType,
        targetReferenceType: null,
        targetReferenceId: null,
        targetReceipt: null,
        resultSummary: null,
        executionCount: 1,
        scheduledAt: scheduledAt ?? null,
        startedAt: now,
        acceptedAt: null,
        lastStartedAt: now,
